// 한 줄(개행 없는 문자열)을 이스케이프 코드 문자열로 변환
function convertLine(line) {
  let output = "";
  let prevAddr = "";
  for (const ch of Array.from(line)) {
    const entry = FONT_DATA[ch];
    if (!entry) {
      // 어떤 폰트 시트에도 없는 문자는 건너뜀 (GBSFM.py와 동일한 동작)
      continue;
    }
    const [addrCode, tileIndex] = entry;
    const placeholder = DEFAULT_MAPPING[tileIndex];
    if (placeholder === undefined) {
      continue;
    }
    output += addrCode === prevAddr ? placeholder : addrCode + placeholder;
    prevAddr = addrCode;
  }
  return output;
}

function convertText(text) {
  return String(text)
    .split("\n")
    .map(convertLine)
    .join("\n");
}

